('SACPCMP','South African Council for the Project and Construction Management Professions',3,'credits','A three-year cycle commonly records 300 credits split across defined categories.',JSON_OBJECT('cycleCredits',300,'categorySplitRequired',true),'approved_value_required','Pack 22 research matrix; category splits require current official confirmation.','pack22-2026-08-29','2026-08-29'),
('SACPLAN','South African Council for Planners',3,'points','A three-year cycle commonly records 75 points across planning categories.',JSON_OBJECT('cyclePoints',75,'primaryCategory','category_a_professional_knowledge'),'approved_value_required','Pack 22 research matrix; confirm current official rules before production reliance.','pack22-2026-08-29','2026-08-29'),
('SACLAP','South African Council for the Landscape Architectural Profession',NULL,'credits','Category 1 personal and professional development is tracked under body-specific approval.',JSON_OBJECT('primaryCategory','category_1_personal_professional_development'),'approved_value_required','Pack 22 research matrix; confirm cycle and values against current official rules.','pack22-2026-08-29','2026-08-29'),
